"""Record actual coordinator visual review after the direction audit is closed."""
from export_common import *
def main():
 p=HERE/'batches/root.json';m=read(p);v=read(HERE/'qa/root-validation.json');assert v['sourceCount']==367 and not v['errors']
 direction=read(HERE/'qa/root-direction-audit.json');assert direction.get('status','').startswith('pass')or direction.get('passed') is True,direction.get('status')
 names=[f'root-compat-{n:02}.png'for n in range(1,9)]+['root-assembly-01.png','root-assembly-02.png','storage-cores-01-light.jpg','logic-01-light.jpg','logistics-special-04-light.jpg','sandbox-world-final-01-light.jpg','defense-walls-01-dark.jpg','logistics-nodes-01-light.jpg','liquid-machinery-04-dark.jpg','conduits-advanced-03-light.jpg','conveyors-connections-01-light.jpg','ducts-conduit-connections-02-dark.jpg','payload-and-doors-01-dark.jpg']
 # These exact sheets were opened and inspected by the coordinator, including changed sheets 03/04/07/08 after the repairs.
 review={'reviewedAt':datetime.now(timezone.utc).isoformat(),'status':'passed_static_art_and_integrity_runtime_unverified','sourceCount':367,'errors':[],'visualReviewEvidence':'All eight compatible contact sheets and the listed native contacts were actually opened. Changed contacts were re-opened after corrections. Both layer assembly sheets were inspected with actual original liquid padding.','checks':['Source paths, hashes, dimensions and 60 distinct conveyor phase frames passed.','Original liquid fill windows and connection alpha are exact.','Doors retain full original open-frame silhouettes and transparent passages.','Large core thrusters mirror to face outward; all six core four-way assemblies were inspected.','Stack conveyor concept art rotates clockwise to the renderer east-facing baseline.','Fixed directional glyphs are removed from stationary router bodies; rotating indicators retain original canvases/pivots; underflow and legacy liquid top indicators are fitted within the new body bounds.','Decorative wall thruster uses a separate base and top.','Legacy liquid-overflow-gate source art is exported but has no active v160.7 block definition.'], 'sheets':[{'file':rel(HERE/'qa'/n),'sha256':sha(HERE/'qa'/n),'actuallyViewed':True}for n in names], 'numericalValidation':'full-game/blocks/qa/root-validation.json','directionAudit':{'file':'full-game/blocks/qa/root-direction-audit.json','sha256':sha(HERE/'qa/root-direction-audit.json')},'runtimeIntegrationVerified':False}
 write(HERE/'qa/root-final-review.json',review)
 for a in m['sourceMappings']:
  assert sha(ROOT/a['file'])==a['sha256'];a['status']='art_export_complete_runtime_unverified';write(ROOT/a['record'],a)
 m.update(status='art_export_complete_runtime_unverified',review='full-game/blocks/qa/root-final-review.json',reviewedAt=review['reviewedAt'],staticReviewPending=False)
 write(p,m);print(json.dumps({'sourceCount':367,'status':m['status'],'batchSha256':sha(p)}))
if __name__=='__main__':main()
